import dorgl2 = require( './index' );


// TESTS //

// The function returns a number...
{
	const A = new Float64Array( 12 );
	const TAU = new Float64Array( 2 );
	const work = new Float64Array( 3 );
	dorgl2( 'row-major', 3, 4, 2, A, 3, TAU, work ); // $ExpectType number
}

// The compiler throws an error if the function is provided a first argument which is not a valid layout...
{
	const A = new Float64Array( 12 );
	const TAU = new Float64Array( 2 );
	const work = new Float64Array( 3 );
	dorgl2( 5, 3, 4, 2, A, 3, TAU, work ); // $ExpectError
	dorgl2( true, 3, 4, 2, A, 3, TAU, work ); // $ExpectError
	dorgl2( false, 3, 4, 2, A, 3, TAU, work ); // $ExpectError
	dorgl2( null, 3, 4, 2, A, 3, TAU, work ); // $ExpectError
	dorgl2( void 0, 3, 4, 2, A, 3, TAU, work ); // $ExpectError
	dorgl2( [], 3, 4, 2, A, 3, TAU, work ); // $ExpectError
	dorgl2( {}, 3, 4, 2, A, 3, TAU, work ); // $ExpectError
	dorgl2( ( x: number ): number => x, 3, 4, 2, A, 3, TAU, work ); // $ExpectError
}

// The compiler throws an error if the function is provided a second argument which is not a number...
{
	const A = new Float64Array( 12 );
	const TAU = new Float64Array( 2 );
	const work = new Float64Array( 3 );
	dorgl2( 'row-major', '3', 4, 2, A, 3, TAU, work ); // $ExpectError
	dorgl2( 'row-major', true, 4, 2, A, 3, TAU, work ); // $ExpectError
	dorgl2( 'row-major', false, 4, 2, A, 3, TAU, work ); // $ExpectError
	dorgl2( 'row-major', null, 4, 2, A, 3, TAU, work ); // $ExpectError
	dorgl2( 'row-major', void 0, 4, 2, A, 3, TAU, work ); // $ExpectError
	dorgl2( 'row-major', [], 4, 2, A, 3, TAU, work ); // $ExpectError
	dorgl2( 'row-major', {}, 4, 2, A, 3, TAU, work ); // $ExpectError
	dorgl2( 'row-major', ( x: number ): number => x, 4, 2, A, 3, TAU, work ); // $ExpectError
}

