// The compiler throws an error if the function is provided an unsupported number of arguments...
{
	const A = new Float64Array( 12 );
	const TAU = new Float64Array( 2 );
	const work = new Float64Array( 3 );
	dorgl2(); // $ExpectError
	dorgl2( 'row-major' ); // $ExpectError
	dorgl2( 'row-major', 3 ); // $ExpectError
	dorgl2( 'row-major', 3, 4 ); // $ExpectError
	dorgl2( 'row-major', 3, 4, 2 ); // $ExpectError
	dorgl2( 'row-major', 3, 4, 2, A ); // $ExpectError
	dorgl2( 'row-major', 3, 4, 2, A, 3 ); // $ExpectError
	dorgl2( 'row-major', 3, 4, 2, A, 3, TAU ); // $ExpectError
	dorgl2( 'row-major', 3, 4, 2, A, 3, TAU, work, 10 ); // $ExpectError
}

// Attached to main export is an `ndarray` method which returns a number...
{
	const A = new Float64Array( 12 );
	const TAU = new Float64Array( 2 );
	const work = new Float64Array( 3 );
	dorgl2.ndarray( 3, 4, 2, A, 4, 1, 0, TAU, 1, 0, work, 1, 0 ); // $ExpectType number
}

// The compiler throws an error if the `ndarray` method is provided a first argument which is not a number...
{
	const A = new Float64Array( 12 );
	const TAU = new Float64Array( 2 );
	const work = new Float64Array( 3 );
	dorgl2.ndarray( 'left', 4, 2, A, 4, 1, 0, TAU, 1, 0, work, 1, 0 ); // $ExpectError
	dorgl2.ndarray( true, 4, 2, A, 4, 1, 0, TAU, 1, 0, work, 1, 0 ); // $ExpectError
	dorgl2.ndarray( false, 4, 2, A, 4, 1, 0, TAU, 1, 0, work, 1, 0 ); // $ExpectError
	dorgl2.ndarray( null, 4, 2, A, 4, 1, 0, TAU, 1, 0, work, 1, 0 ); // $ExpectError
	dorgl2.ndarray( void 0, 4, 2, A, 4, 1, 0, TAU, 1, 0, work, 1, 0 ); // $ExpectError
	dorgl2.ndarray( [], 4, 2, A, 4, 1, 0, TAU, 1, 0, work, 1, 0 ); // $ExpectError
	dorgl2.ndarray( {}, 4, 2, A, 4, 1, 0, TAU, 1, 0, work, 1, 0 ); // $ExpectError
	dorgl2.ndarray( ( x: number ): number => x, 4, 2, A, 4, 1, 0, TAU, 1, 0, work, 1, 0 ); // $ExpectError
}

